const learningPlan = mountLearningPlan();

function setPrimaryNavigation(section = 'tutor') {
  if(section !== 'tutor') setConversationFocus(false);
  const views = {tutor: ['nav-talk', 'mobile-talk'], lessons: ['nav-teacher', 'mobile-teacher'], assignments: ['nav-assignments', 'mobile-assignments'], progress: ['nav-progress', 'mobile-progress']};
  for (const [view, ids] of Object.entries(views)) for (const id of ids) {
    const control = $(id); if (!control) continue;
    control.classList.toggle('active', view === section);
    if (view === section) control.setAttribute('aria-current', 'page');
    else control.removeAttribute('aria-current');
  }
}
function setConversationFocus(focused) {
  conversationFocused = Boolean(focused);
  document.body.classList.toggle('conversation-focused', conversationFocused);
  const back = $('classroom-home'); if(back) back.hidden = !conversationFocused;
  const heading = $('classroom-heading');
  if(heading) heading.textContent = conversationFocused ? `Talk with ${state.profile.companionName}.` : `Your classroom with ${state.profile.companionName}.`;
}
function updateTutorHint() {
  $('composer-note').textContent = activeTeacherContext ? 'Ask about this lesson. Hiroshi can explain it and help you practise step by step.' : chatMode() === 'live' ? 'Talk with Hiroshi, ask a question, or practise a Japanese phrase.' : 'Guided scene: practise a suggested reply. Open Lessons for explanations and Assignments for your tasks.';
}
function outstandingAssignments() {
  return state.teacher.assignments.filter(assignment => assignment.latestScore !== LESSONS.find(lesson => lesson.id === assignment.lessonId)?.homework.length
    || assignment.attempts.at(-1)?.results.some(result => (assignment.answers[result.exerciseId] || '') !== result.answer));
}
function mountLearningPlan() {
  const anchor = document.querySelector('.game-layout');
  const card = node('section', 'learning-plan'); card.id = 'learning-plan'; card.setAttribute('aria-labelledby', 'learning-plan-title');
  const copy = node('div', 'plan-copy'), title = node('h2'), summary = node('p', 'plan-summary'), status = node('p', 'plan-status');
  title.id = 'learning-plan-title';
  copy.append(node('p', 'eyebrow', 'YOUR NEXT STEP'), title, summary, status);
  const actions = node('div', 'plan-actions');
  const teach = button('Open lesson', 'primary-button', () => {
    void learningUI.continueLearning();
  }); teach.id = 'plan-teach';
  const assignments = button('Assignments', 'secondary-button', openLearningAssignments); assignments.id = 'plan-assignments';
  const review = button('Course library', 'text-button', () => teacherUI.show()); review.id = 'plan-review';
  actions.append(teach, assignments, review); card.append(copy, actions); anchor.before(card);
  return {title, summary, status, teach, assignments, review};
}
function updateLearningPlan() {
  const summary=getLearningSummary(state.learning), active=summary.activeUnit;
  const pending=outstandingAssignments().length+summary.pendingAssignments;
  const difficulty=active?.lesson?.difficulty||summary.next.difficulty;
  const level=({1:'With help',2:'On your own',3:'Challenge'})[difficulty]||'With help';
  learningPlan.title.textContent=active?.lesson?.title||summary.next.label;
  learningPlan.summary.textContent=active ? (active.phase==='assignment'?'Your practice is done. Continue your saved assignment and review its feedback.':active.lesson.objective) : summary.next.reason;
  learningPlan.status.textContent=`${summary.completedUnits} saved personal lessons completed · ${pending} assignment${pending===1?'':'s'} to work on · ${level}`;
  learningPlan.teach.textContent=active?'Continue my lesson':liveConfigured&&aiProvider==='chatgpt'?'Create my next lesson':'Start step-by-step lesson';
  learningPlan.teach.title=active?'Resume your saved teaching and practice':liveConfigured&&aiProvider==='chatgpt'?'Ask Hiroshi for a lesson based on your practice history':'Use a prepared lesson matched to your practice history';
  learningPlan.assignments.textContent=pending?`Open assignment (${pending})`:'Assignments';
  learningPlan.review.hidden=false;
  for(const id of ['assignment-count','mobile-assignments-count']){const badge=$(id);if(badge){badge.textContent=pending;badge.hidden=pending===0;}}
  if($('homework-count'))$('homework-count').hidden=true;
}
function openLearningAssignments(){
  const summary=getLearningSummary(state.learning);
  if(summary.pendingAssignments>0)return learningUI.showAssignments();
  if(outstandingAssignments().length||(!state.learning.units.length&&!state.teacher.assignments.length))return teacherUI.showAssignments();
  return learningUI.showAssignments();
}

