function renderMessage(msg){const article=node('article',`message ${msg.role}`);article.dataset.messageId=msg.id;const caption=node('div','message-caption');if(msg.role==='assistant')caption.append(node('span','avatar-dot','✦'));caption.append(document.createTextNode(msg.role==='assistant'?state.profile.companionName:(state.profile.name||'You')));article.append(caption);const bubble=node('div','message-bubble');const text=node('p','message-text',msg.role==='user'?msg.text:msg.reply);text.lang=msg.role==='user'?'':chatLanguage();bubble.append(text);if(msg.role==='assistant'){if(msg.reading)bubble.append(node('p','reading',msg.reading));if(msg.translation)bubble.append(node('p','translation',msg.translation));}article.append(bubble);if(msg.role==='assistant'){const actions=node('div','message-actions');const listen=button('Listen','',()=>speak(msg.reply,chatLanguage(),listen),'volume');listen.setAttribute('aria-label',`Listen to ${msg.reply.slice(0,65)}`);actions.append(listen);const saved=isSaved(msg);const saveBtn=button(saved?'Saved':'Save phrase',saved?'saved':'',()=>togglePhrase(msg,saveBtn),saved?'check':'bookmark');saveBtn.setAttribute('aria-pressed',String(saved));actions.append(saveBtn);article.append(actions);if(msg.correction&&state.preferences.corrections)article.append(node('p','correction',msg.correction));}$('messages').append(article);return article;}
