async function checkConnection(force=false){
  if(chatGPTConnection.enabled){await chatGPTConnection.ready;const data=force?await chatGPTConnection.refresh():chatGPTConnection.snapshot();liveConfigured=data.configured===true;aiProvider=liveConfigured?'chatgpt':'none';}
  else if(!APP_CONFIG.apiBase){liveConfigured=false;aiProvider='none';}
  else try{const response=await appFetch(`${APP_CONFIG.apiBase}/status`,{cache:'no-store',signal:AbortSignal.timeout(5000)});const data=await response.json();liveConfigured=response.ok&&data.configured===true;aiProvider=liveConfigured?(data.provider==='local'?'local':data.provider==='chatgpt'?'chatgpt':'openai'):'none';}catch{liveConfigured=false;aiProvider='none';}
  statusChecked=true;
  if(liveConfigured&&(!state.preferences.modeChosen||webConnectionActivateLive)){const approvedNow=webConnectionActivateLive;webConnectionActivateLive=false;state.preferences.mode='live';if(approvedNow)state.preferences.modeChosen=true;save();renderConversation();}
  if(state.preferences.mode==='live'&&!liveConfigured){if(chatGPTConnection.enabled&&chatGPTConnection.snapshot().stage==='offline'){updateIdentity();return;}state.preferences.mode='guided';if(!['ja','en'].includes(state.preferences.language))state.preferences.language='ja';save();renderConversation();}else updateIdentity();
}
const installUI=createInstallUI({openModal,toast,getName:()=>APP_CONFIG.name,getConnection:()=>({configured:liveConfigured,provider:aiProvider}),onExportBackup:exportBackup});
function learningMemory() {
  const summary=getLearningSummary(state.learning);
  return {difficulty:summary.activeUnit?.lesson?.difficulty||summary.next.difficulty,
    weaknesses:summary.weaknesses.slice(0,6).map(item=>({prompt:clean(item.prompt,240),feedback:clean(item.feedback,400),answer:clean(item.answer,240)}))};
}
function conversationMemories(){
  const summary=getLearningSummary(state.learning);
  if(!summary.activeUnit&&!summary.weaknesses.length&&!summary.skills.some(skill=>skill.attempts))return state.memories;
  const level=({1:'With help',2:'On your own',3:'Challenge'})[summary.next.difficulty];
  const struggles=summary.weaknesses.slice(0,2).map(item=>item.prompt).join('; ');
  const note=clean(`Saved Japanese learning: ${summary.next.label}; support: ${level}. ${struggles?`Practise again: ${struggles}`:'Use a small next step and one practice question at a time.'}`,250);
  return [...state.memories.slice(-11),note];
}
function teacherConversationContext(){return aiProvider==='chatgpt'?{...activeTeacherContext,learningMemory:learningMemory()}:activeTeacherContext;}
function askTeacher(context,question){if(!liveConfigured){toast(chatGPTConnection.enabled?'Open Settings to connect your ChatGPT plan for an AI explanation. Lessons and homework are ready now.':'Start the local companion to ask for an AI explanation. Lessons and homework are ready now.');return false;}if(busy){toast(`Let ${state.profile.companionName} finish replying, then ask about your lesson.`);return false;}if($('message-input').value.trim()){toast('Send or clear your current message before starting lesson help.');return false;}resetPending();activeTeacherContext=context;setPrimaryNavigation('tutor');setConversationFocus(true);renderConversation();$('modal').close();$('message-input').value=question;resizeComposer();document.querySelector('.conversation-panel').scrollIntoView({behavior:'smooth',block:'end'});sendMessage();return true;}
async function generateLearningLesson(recommendation,{signal,learningSummary}={}) {
  if(!liveConfigured||aiProvider!=='chatgpt'||!chatGPTConnection.enabled)throw new Error('Connect your ChatGPT plan in Settings to create a personalized AI lesson. Prepared lessons are ready now.');
  if(typeof APP_CONFIG.apiBase!=='string'||new URL(APP_CONFIG.apiBase,APP_CONFIG.chatgptBackend).href.replace(/\/$/,'')!==new URL('/api/hiroshi',APP_CONFIG.chatgptBackend).href)throw new Error('The personalized lesson connection is not configured correctly. Your saved learning is safe.');
  if(busy)throw new Error('Let Hiroshi finish the current reply before creating a lesson.');
  const summary=learningSummary||getLearningSummary(state.learning);
  const weaknesses=(summary.weaknesses||[]).filter(item=>!item.skillId||item.skillId===recommendation.skillId).slice(0,6)
    .map(item=>({prompt:clean(item.prompt,240),feedback:clean(item.feedback,400),answer:clean(item.answer,240)}));
  const controller=new AbortController(), abort=()=>controller.abort();
  if(signal?.aborted)throw new DOMException('Lesson cancelled','AbortError');
  signal?.addEventListener('abort',abort,{once:true});
  const timer=setTimeout(abort,150000);
  setBusy(true);
  try{
    const response=await appFetch(`${APP_CONFIG.apiBase}/lesson`,{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,
      body:JSON.stringify({skillId:recommendation.skillId,difficulty:recommendation.difficulty,reason:clean(recommendation.reason,400),weaknesses,
        recentLessons:state.learning.units.slice(-8).map(unit=>clean(unit.lesson.title,160)),profile:{name:clean(state.profile.name,60),interests:clean(state.profile.interests,500)}})});
    const result=await response.json().catch(()=>null);
    if(!response.ok)throw new Error(clean(result?.error?.message,350)||'Hiroshi could not create a lesson. Your saved learning is unchanged.');
    if(!result?.lesson)throw new Error('Hiroshi did not return a complete lesson. Try again or use a prepared lesson.');
    return result.lesson;
  }finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);setBusy(false);}
}
