setPrimaryNavigation('tutor');
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
$('mic-button').addEventListener('click',()=>{if(!SpeechRecognition){toast('Dictation isn’t available here. You can use your device keyboard’s microphone.');return;}if(recognition){recognition.stop();return;}recognition=new SpeechRecognition();recognition.lang=({ja:'ja-JP',en:'en-US',es:'es-ES',ko:'ko-KR'})[chatLanguage()];recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onresult=e=>{$('message-input').value=clean(e.results[0][0].transcript);resizeComposer();$('message-input').focus();};recognition.onerror=e=>toast(e.error==='not-allowed'?'Microphone access wasn’t allowed. You can still type your message.':'Dictation didn’t catch that. Please try again or type your message.');recognition.onend=()=>{recognition=null;$('mic-button').classList.remove('recording');$('mic-button').setAttribute('aria-label','Dictate a message');};try{recognition.start();$('mic-button').classList.add('recording');$('mic-button').setAttribute('aria-label','Stop dictation');toast('Listening. Dictation fills the box; you choose when to send.');}catch{recognition=null;toast('Your browser couldn’t start dictation.');}});
configurePrivateChat();renderConversation();checkConnection();if(!storageAvailable)setTimeout(()=>toast('Storage wasn’t available or your save couldn’t be read. Use backups to keep your progress.'),1000);
startWebUpdates({native:APP_CONFIG.native===true,canReload:()=>!busy&&!chatGPTConnection.snapshot().busy&&!$('message-input').value.trim()&&!$('modal').open,toast});
window.addEventListener('online',()=>{void checkConnection(true);});
